#include <bits/stdc++.h>
#define rep(XX, AA, BB) for (int XX = (AA); XX <= (BB); ++XX)
using namespace std;

using LL = long long;

const int K = 14;
const int M = 1 << 4;
const int MX = 310;
const LL MOD = 1000000007LL;

int n, m, k;
int tot = 0, maxn;
int id[K][M];

void read(int &x) {
    int c = getchar();
    while (c != EOF && (c < '0' || c > '9')) c = getchar();
    x = 0;
    while (c >= '0' && c <= '9') {
        x = x * 10 + (c - '0');
        c = getchar();
    }
}

struct Matrix {
    LL a[MX][MX];

    void clear() {
        rep(i, 0, tot)
            rep(j, 0, tot)
                a[i][j] = 0;
    }
} hlp;

Matrix multiply(const Matrix &A, const Matrix &B) {
    Matrix C;
    C.clear();

    rep(i, 1, tot)
        rep(r, 1, tot) {
            if (A.a[i][r] == 0) continue;
            rep(j, 1, tot) {
                C.a[i][j] =
                    (C.a[i][j] + A.a[i][r] * B.a[r][j]) % MOD;
            }
        }

    return C;
}

LL power(int y) {
    Matrix res;
    res.clear();
    res.a[1][1] = 1;

    while (y > 0) {
        if (y & 1) res = multiply(res, hlp);
        hlp = multiply(hlp, hlp);
        y >>= 1;
    }

    LL ans = 0;
    rep(num, 0, maxn)
        ans = (ans + res.a[1][id[k][num]]) % MOD;

    return ans;
}

int main() {
    read(n);
    read(k);
    read(m);

    maxn = (1 << m) - 1;

    rep(i, 0, k)
        rep(j, 0, maxn)
            id[i][j] = ++tot;

    rep(len, 0, k)
        rep(num, 0, maxn) {
            int num1 = (num << 1) & maxn;
            hlp.a[id[len][num]][id[len][num1]] = 1;

            if (len < k) {
                hlp.a[id[len][num]][id[len + 1][num1 | 1]] =
                    __builtin_popcount(static_cast<unsigned>(num)) + 1;
            }
        }

    printf("%lld\n", power(n));
    return 0;
}

